def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    if n >= 99:
        return 'D'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    if all(a == 'D' for a in opp):
        return 'D'
    if all(a == 'C' for a in opp):
        return 'C'
    if n >= 10:
        for p in range(2, 9):
            if n > p and all(opp[i] == opp[i-p] for i in range(p, n)):
                return 'D'
    last_my, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    else:
        consec_d = 0
        for i in range(n-1, -1, -1):
            if opp[i] == 'D':
                consec_d += 1
            else:
                break
        if consec_d >= 3:
            if last_my == 'D':
                return 'C'
            else:
                return 'D'
        elif consec_d == 2:
            return 'D'
        else:
            return 'D'
